  AND NOT EXISTS (
    SELECT 1
    FROM (VALUES
  ('Rice___Blast', 'NEWTEC_300SC'),
  ('Rice___Sheath_blight', 'NEWTEC_300SC'),
  ('Rice___Brown_spot', 'HELP_400SC')
    ) AS desired(disease_code, pesticide_code)
    WHERE desired.disease_code = d.code
      AND desired.pesticide_code = p.code
  );

